insert into passages (id, text, difficulty_level, b, active) values
('57017dab-bd59-405c-afbd-465513e0028c', 'Volcanoes have long fascinated scientists and the public alike, not only for their destructive power but also for the essential role they play in shaping the planet''s landscape. When a volcano erupts, it releases molten rock, ash, and gases from deep within the Earth, sometimes with enough force to alter local climate for years afterward. While eruptions can cause tremendous damage to nearby communities, volcanic activity has also created some of the most fertile soil on Earth, since volcanic ash is rich in minerals that plants need to grow. This is why many farming communities have historically settled near volcanoes despite the risks involved. Modern monitoring technology, including seismic sensors and satellite imaging, now allows scientists to detect warning signs before major eruptions, giving nearby populations valuable time to evacuate. Even so, predicting the exact timing of an eruption remains extremely difficult, and volcanologists continue to study past eruptions to improve their forecasting models.', 3, 0.0, true),
('d809e3b1-e150-4b6f-a6c8-e7dd158e644c', 'Fast fashion, the practice of rapidly producing inexpensive clothing to match the latest trends, has transformed the retail industry over the past two decades. Major clothing chains can now design, manufacture, and deliver new styles to stores within a matter of weeks, allowing consumers to purchase trendy items at low prices with unprecedented speed. However, this business model has drawn significant criticism from environmental and labor rights groups. The rapid production cycle often relies on cheap synthetic materials that shed microplastics when washed and that decompose slowly in landfills once discarded. Additionally, the pressure to produce clothing quickly and cheaply has been linked to poor working conditions and low wages in many garment factories. In response to growing public awareness, some companies have introduced clothing recycling programs and begun using more sustainable materials, though critics argue that these efforts remain small compared to the overall scale of production. Meanwhile, a growing movement toward secondhand and slow fashion encourages consumers to buy fewer, higher-quality garments that last longer.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('d8c27b20-6dcd-4d2c-89a2-c529312940b1', 'sentence_completion', 'The committee will ___ the proposal at next week''s meeting.', NULL, '[{"id": "c", "text": "review"}, {"id": "a", "text": "ignore"}, {"id": "d", "text": "forget"}, {"id": "b", "text": "hide"}]'::jsonb, 0, '{"strategy": "next week''s meeting = פגישה בשבוע הבא. מה עושה ועדה עם הצעה בפגישה?", "correct_reason": "review = לבחון/לדון. ועדות דנות בהצעות בפגישות.", "options_analysis": ["נכון! review = לבחון — פעולה טבעית של ועדה בפגישה", "ignore = להתעלם מ- — לא הגיוני לוועדה", "forget = לשכוח — לא רלוונטי לסדר יום", "hide = להסתיר — לא רלוונטי"]}', 1.16, 0.0, 0.25, 3, 'ai', NULL, true),
('edd7ffff-424c-49e2-ac01-d1e77596089e', 'sentence_completion', 'The manager was ___ with the team''s progress on the new project.', NULL, '[{"id": "d", "text": "disappointed"}, {"id": "a", "text": "satisfied"}, {"id": "c", "text": "angry"}, {"id": "b", "text": "confused"}]'::jsonb, 1, '{"strategy": "progress on the new project = התקדמות בפרויקט. אם ההתקדמות טובה, איך המנהל מרגיש?", "correct_reason": "satisfied = מרוצה. התקדמות טובה גורמת לשביעות רצון.", "options_analysis": ["disappointed = מאוכזב — לא מתאים אלא אם צוין שההתקדמות גרועה", "נכון! satisfied = מרוצה — מתאים לתגובה חיובית סטנדרטית", "angry = כועס — לא קשור להתקדמות", "confused = מבולבל — לא קשור להתקדמות"]}', 1.51, 0.0, 0.25, 3, 'ai', NULL, true),
('25a2d863-cdfc-4596-857e-9cd668ef7484', 'sentence_completion', 'The bridge collapsed because engineers had ___ the weight it could hold.', NULL, '[{"id": "b", "text": "celebrated"}, {"id": "d", "text": "reported"}, {"id": "c", "text": "overestimated"}, {"id": "a", "text": "measured"}]'::jsonb, 2, '{"strategy": "collapsed = קרס. למה קרס גשר?", "correct_reason": "overestimated = העריכו יתר על המידה. הערכת יתר של כושר הנשיאה גורמת לקריסה.", "options_analysis": ["celebrated = חגגו — לא רלוונטי", "reported = דיווחו — לא מסביר קריסה", "נכון! overestimated = הפריזו בהערכה — מסביר למה הגשר לא עמד בעומס", "measured = מדדו — לא מסביר קריסה"]}', 0.91, 0.0, 0.25, 3, 'ai', NULL, true),
('1e195216-0b8b-488a-9ba0-cd09f04f3c0e', 'sentence_completion', 'The company''s profits ___ significantly after the new product launch.', NULL, '[{"id": "b", "text": "ignored"}, {"id": "d", "text": "disappeared"}, {"id": "c", "text": "decreased"}, {"id": "a", "text": "increased"}]'::jsonb, 3, '{"strategy": "after the new product launch = אחרי השקת המוצר. מה קורה לרווחים אחרי מוצר מצליח?", "correct_reason": "increased = עלו. מוצר חדש מצליח מגדיל רווחים.", "options_analysis": ["ignored = התעלמו מ- — לא רלוונטי לרווחים", "disappeared = נעלמו — לא הגיוני", "decreased = ירדו — לא הגיוני להשקה מוצלחת", "נכון! increased = עלו — תוצאה טבעית של השקה מוצלחת"]}', 1.32, 0.0, 0.25, 3, 'ai', NULL, true),
('62fd5d3e-31a2-466b-bab3-c84bfe00c465', 'sentence_completion', 'The scientist''s research was later ___ by other experts in the field.', NULL, '[{"id": "d", "text": "confirmed"}, {"id": "a", "text": "sold"}, {"id": "c", "text": "forgotten"}, {"id": "b", "text": "painted"}]'::jsonb, 0, '{"strategy": "later ___ by other experts = אושר מאוחר יותר ע''י מומחים אחרים.", "correct_reason": "confirmed = אושר. מחקר מדעי מאושש ע''י מומחים אחרים.", "options_analysis": ["נכון! confirmed = אושש — פעולה טבעית של מומחים למחקר קודם", "sold = נמכר — לא רלוונטי למחקר", "forgotten = נשכח — סותר ''by other experts''", "painted = נצבע — חסר משמעות"]}', 0.93, 0.0, 0.25, 3, 'ai', NULL, true),
('bae5c68f-66a8-4ea0-837b-6d64aecabff3', 'sentence_completion', 'The government announced a new plan to ___ unemployment rates.', NULL, '[{"id": "b", "text": "increase"}, {"id": "c", "text": "reduce"}, {"id": "d", "text": "ignore"}, {"id": "a", "text": "celebrate"}]'::jsonb, 1, '{"strategy": "new plan = תוכנית חדשה. מה ממשלה עושה לאבטלה?", "correct_reason": "reduce = להפחית. תוכניות ממשלתיות נועדו בד''כ להפחית אבטלה.", "options_analysis": ["increase = להגדיל — הפוך ממטרת מדיניות", "נכון! reduce = להפחית — מטרה טבעית של תוכנית ממשלתית", "ignore = להתעלם מ- — לא הגיוני", "celebrate = לחגוג — לא רלוונטי"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('7d6bd965-b87c-4e2c-888e-46a8501ce407', 'sentence_completion', 'The restaurant had to ___ its menu after customers complained about the prices.', NULL, '[{"id": "a", "text": "ignore"}, {"id": "d", "text": "expand"}, {"id": "c", "text": "revise"}, {"id": "b", "text": "celebrate"}]'::jsonb, 2, '{"strategy": "after customers complained about prices = אחרי תלונות על מחירים. מה עושה מסעדה בתגובה?", "correct_reason": "revise = לתקן/לעדכן. תלונות על מחירים מובילות לעדכון תפריט.", "options_analysis": ["ignore = להתעלם מ- — פחות סביר מעדכון", "expand = להרחיב — לא מסביר תגובה לתלונה", "נכון! revise = לעדכן — תגובה הגיונית לתלונות", "celebrate = לחגוג — לא רלוונטי"]}', 1.43, 0.0, 0.25, 3, 'ai', NULL, true),
('324c7909-6b5e-4a56-9192-a1898c3211b0', 'sentence_completion', 'The lawyer ___ the client''s case with strong evidence.', NULL, '[{"id": "b", "text": "hid"}, {"id": "a", "text": "weakened"}, {"id": "c", "text": "ignored"}, {"id": "d", "text": "supported"}]'::jsonb, 3, '{"strategy": "with strong evidence = עם ראיות חזקות. מה עושות ראיות חזקות לתיק?", "correct_reason": "supported = תמכו ב-. ראיות חזקות תומכות בתיק.", "options_analysis": ["hid = הסתירו — לא רלוונטי לתיק משפטי", "weakened = החלישו — הפוך מראיות חזקות", "ignored = התעלמו מ- — לא רלוונטי", "נכון! supported = תמכו — ראיות חזקות תומכות בתיק"]}', 1.19, 0.0, 0.25, 3, 'ai', NULL, true),
('c4b70b77-3e4c-406f-81b4-3136f75c5166', 'sentence_completion', 'The hurricane caused widespread ___ to homes along the coast.', NULL, '[{"id": "d", "text": "damage"}, {"id": "b", "text": "benefit"}, {"id": "c", "text": "improvement"}, {"id": "a", "text": "celebration"}]'::jsonb, 0, '{"strategy": "hurricane = הוריקן. מה גורם הוריקן לבתים?", "correct_reason": "damage = נזק. הוריקן גורם נזק לבתים.", "options_analysis": ["נכון! damage = נזק — תוצאה טבעית של הוריקן", "benefit = תועלת — הפוך מתוצאה של הוריקן", "improvement = שיפור — הפוך מתוצאה של הוריקן", "celebration = חגיגה — לא רלוונטי"]}', 1.47, 0.0, 0.25, 3, 'ai', NULL, true),
('fdb897b3-93eb-4c17-a94c-e6204d9b7e91', 'sentence_completion', 'The airline had to ___ several flights due to the mechanical issue.', NULL, '[{"id": "b", "text": "publish"}, {"id": "c", "text": "ground"}, {"id": "a", "text": "celebrate"}, {"id": "d", "text": "enjoy"}]'::jsonb, 1, '{"strategy": "mechanical issue = תקלה מכנית. מה עושה חברת תעופה עם טיסות בגלל תקלה?", "correct_reason": "ground = לקרקע. תקלה מכנית מחייבת קרקוע טיסות מטעמי בטיחות.", "options_analysis": ["publish = לפרסם — לא פעולה מבצעית", "נכון! ground = לקרקע — פעולת בטיחות סטנדרטית בתקלה מכנית", "celebrate = לחגוג — לא רלוונטי", "enjoy = ליהנות מ- — לא רלוונטי"]}', 1.54, 0.0, 0.25, 3, 'ai', NULL, true),
('5ec9cc25-589f-47f8-914b-77abe9cf585a', 'sentence_completion', 'The professor''s lecture ___ several complex ideas in simple terms.', NULL, '[{"id": "a", "text": "confused"}, {"id": "d", "text": "ignored"}, {"id": "c", "text": "explained"}, {"id": "b", "text": "hid"}]'::jsonb, 2, '{"strategy": "in simple terms = במונחים פשוטים. מה עושה הרצאה טובה לרעיונות מורכבים?", "correct_reason": "explained = הסבירה. הרצאה טובה מסבירה רעיונות מורכבים בפשטות.", "options_analysis": ["confused = בלבלה — הפוך מהסבר בהיר", "ignored = התעלמה מ- — לא רלוונטי", "נכון! explained = הסבירה — מתאים ל''in simple terms''", "hid = הסתירה — הפוך ממטרת הרצאה"]}', 0.98, 0.0, 0.25, 3, 'ai', NULL, true),
('bd305919-ef9c-47f3-9aaf-6974fda4241a', 'sentence_completion', 'The factory implemented new safety measures to ___ workplace accidents.', NULL, '[{"id": "a", "text": "increase"}, {"id": "c", "text": "celebrate"}, {"id": "b", "text": "ignore"}, {"id": "d", "text": "prevent"}]'::jsonb, 3, '{"strategy": "new safety measures = אמצעי בטיחות חדשים. מה מטרתם?", "correct_reason": "prevent = למנוע. אמצעי בטיחות נועדו למנוע תאונות.", "options_analysis": ["increase = להגדיל — הפוך ממטרת בטיחות", "celebrate = לחגוג — לא רלוונטי", "ignore = להתעלם מ- — לא רלוונטי", "נכון! prevent = למנוע — המטרה הטבעית של אמצעי בטיחות"]}', 1.16, 0.0, 0.25, 3, 'ai', NULL, true),
('67c34c47-b08a-4ddf-89a5-c4f13553ffae', 'restatement', 'The store offers a discount to customers who buy in bulk.', NULL, '[{"id": "d", "text": "Customers who buy in bulk receive a discount from the store."}, {"id": "a", "text": "Customers must pay more if they buy in bulk."}, {"id": "b", "text": "The store offers discounts only to new customers."}, {"id": "c", "text": "The store never offers discounts to any customers."}]'::jsonb, 0, '{"strategy": "offers a discount to = מציעה הנחה ל-. פרט על מדיניות החנות.", "correct_reason": "אותה עובדה בדיוק, ניסוח מנקודת מבט הלקוח.", "options_analysis": ["נכון! אותה עובדה בדיוק, מנקודת מבט הלקוח", "הפוך — הנחה, לא תשלום נוסף", "לא נאמר במקור על לקוחות חדשים", "סותר לגמרי — יש הנחה לרוכשים בכמות"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('b73ba703-c12d-43a9-8da5-3d09342aeb46', 'restatement', 'Despite the heavy traffic, she arrived at the meeting on time.', NULL, '[{"id": "c", "text": "She missed the meeting entirely due to traffic."}, {"id": "d", "text": "Even with heavy traffic, she was on time for the meeting."}, {"id": "b", "text": "She arrived late to the meeting because of heavy traffic."}, {"id": "a", "text": "There was no traffic on her way to the meeting."}]'::jsonb, 1, '{"strategy": "despite heavy traffic...on time = למרות פקק, הגיעה בזמן. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר לגמרי — היא כן הגיעה", "נכון! אותה משמעות בדיוק: הגיעה בזמן למרות הפקק", "סותר ''on time'' — היא כן הגיעה בזמן", "סותר ''heavy traffic'' במקור"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('a7a38e8c-5908-4f2e-9f24-0af75000293d', 'restatement', 'The board rejected the proposal because it was too expensive.', NULL, '[{"id": "a", "text": "The proposal''s cost had nothing to do with its rejection."}, {"id": "b", "text": "The board rejected the proposal even though it was cheap."}, {"id": "d", "text": "The proposal was too expensive, so the board rejected it."}, {"id": "c", "text": "The board approved the proposal because it was affordable."}]'::jsonb, 2, '{"strategy": "rejected because too expensive = דחתה כי יקרה מדי. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר את קיום הקשר הסיבתי", "סותר ''too expensive'' — ההצעה כן הייתה יקרה", "נכון! אותה סיבה-תוצאה בדיוק", "הפוך — ''approved'' סותר ''rejected''"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('0ee23307-3e1e-4d80-a055-00fe618d96a2', 'restatement', 'The novel, written over ten years ago, remains popular today.', NULL, '[{"id": "d", "text": "The novel is popular only among older readers."}, {"id": "b", "text": "The novel stopped being popular ten years ago."}, {"id": "a", "text": "The novel was written recently and is already forgotten."}, {"id": "c", "text": "Although it was written over ten years ago, the novel is still popular today."}]'::jsonb, 3, '{"strategy": "written...ago, remains popular = נכתב לפני, נשאר פופולרי. ניגוד/המשכיות.", "correct_reason": "אותה משמעות בדיוק: פופולרי עדיין למרות הזמן שעבר.", "options_analysis": ["לא נאמר במקור הגבלה כזו", "הפוך — ''remains popular today'' סותר הפסקת הפופולריות", "סותר ''over ten years ago'' וגם ''remains popular''", "נכון! אותה משמעות בדיוק: עדיין פופולרי למרות הזמן שעבר"]}', 1.39, 0.0, 0.25, 3, 'ai', NULL, true),
('67175f30-8d60-41c7-b674-3b6918681153', 'restatement', 'The technology allows farmers to monitor their crops remotely.', NULL, '[{"id": "d", "text": "Farmers can monitor their crops from a distance using this technology."}, {"id": "b", "text": "Farmers must be physically present to use this technology."}, {"id": "c", "text": "This technology has nothing to do with farming."}, {"id": "a", "text": "The technology prevents farmers from monitoring their crops."}]'::jsonb, 0, '{"strategy": "monitor remotely = לפקח מרחוק. יכולת טכנולוגית.", "correct_reason": "אותה יכולת בדיוק, ניסוח שונה.", "options_analysis": ["נכון! אותה יכולת בדיוק: פיקוח מרחוק", "סותר ''remotely'' — אין צורך בנוכחות פיזית", "סותר לגמרי — הטכנולוגיה מיועדת לחקלאים", "הפוך — הטכנולוגיה מאפשרת, לא מונעת"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('ddb294b0-8743-4d72-83e9-ec7bb792357a', 'restatement', 'The committee postponed the decision until more information was available.', NULL, '[{"id": "b", "text": "The committee decided immediately, before gathering information."}, {"id": "a", "text": "The committee waited for more information before making the decision."}, {"id": "c", "text": "The committee made the decision without waiting for more information."}, {"id": "d", "text": "The committee never made a decision at all."}]'::jsonb, 1, '{"strategy": "postponed until more information = דחתה עד שתהיה מידע נוסף. תנאי.", "correct_reason": "אותה משמעות בדיוק: המתינו למידע לפני ההחלטה.", "options_analysis": ["סותר ''postponed'' — הם דווקא חיכו", "נכון! אותה משמעות בדיוק: חיכו למידע לפני ההחלטה", "סותר ''postponed until'' — הם כן חיכו", "לא נאמר במקור שלא התקבלה החלטה בסוף"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('1f409314-45b1-4640-bfd3-33e5db668ccd', 'restatement', 'The charity relies heavily on donations from the public.', NULL, '[{"id": "d", "text": "The charity refuses to accept donations from the public."}, {"id": "b", "text": "The charity has never received any donations."}, {"id": "c", "text": "The charity receives most of its support from public donations."}, {"id": "a", "text": "The charity is funded entirely by the government."}]'::jsonb, 2, '{"strategy": "relies heavily on donations = תלויה מאוד בתרומות. פרט תקציב.", "correct_reason": "אותה משמעות בדיוק: רוב התמיכה מגיעה מתרומות ציבור.", "options_analysis": ["סותר לגמרי — הצדקה כן מקבלת תרומות", "סותר ''relies heavily on donations''", "נכון! אותה משמעות בדיוק: תלות עיקרית בתרומות ציבור", "סותר את המקור — אין אזכור למימון ממשלתי"]}', 1.26, 0.0, 0.25, 3, 'ai', NULL, true),
('4fe58343-7fb6-445f-a4a6-2f76fa04a13d', 'restatement', 'The new law requires all restaurants to display calorie information.', NULL, '[{"id": "c", "text": "Restaurants may choose whether to display calorie information."}, {"id": "d", "text": "The new law applies only to fast food chains."}, {"id": "a", "text": "The new law bans restaurants from mentioning calories."}, {"id": "b", "text": "Restaurants are required by the new law to display calorie information."}]'::jsonb, 3, '{"strategy": "requires = מחייב. פעיל לסביל.", "correct_reason": "אותה עובדה בדיוק, בקול סביל.", "options_analysis": ["סותר ''requires'' — זו חובה, לא בחירה", "לא נאמר במקור הגבלה כזו — ''all restaurants''", "הפוך — ''bans'' סותר ''requires''", "נכון! אותה עובדה בדיוק, בקול סביל"]}', 1.13, 0.0, 0.25, 3, 'ai', NULL, true),
('638a65d8-7706-497e-84af-930e126f0479', 'restatement', 'The company''s stock price fell sharply after the disappointing earnings report.', NULL, '[{"id": "b", "text": "After the disappointing earnings report, the stock price fell sharply."}, {"id": "d", "text": "The stock price rose sharply after the earnings report."}, {"id": "a", "text": "The stock price fell before the earnings report was released."}, {"id": "c", "text": "The earnings report had no effect on the stock price."}]'::jsonb, 0, '{"strategy": "fell sharply after = ירד בחדות אחרי. סדר זמן וסיבה-תוצאה.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["נכון! אותה עובדה בדיוק, סדר מילים הפוך", "הפוך — ''rose'' סותר ''fell''", "הופך את סדר האירועים", "סותר את הקשר הסיבתי המפורש במקור"]}', 1.01, 0.0, 0.25, 3, 'ai', NULL, true),
('14a96cca-9cc3-4522-a4b4-a7beda7800e8', 'restatement', 'The museum extended its hours to accommodate the increased number of visitors.', NULL, '[{"id": "a", "text": "The number of visitors decreased after the museum extended its hours."}, {"id": "d", "text": "The museum extended its hours because more visitors were coming."}, {"id": "b", "text": "The museum reduced its hours because of fewer visitors."}, {"id": "c", "text": "The museum''s hours have always been the same."}]'::jsonb, 1, '{"strategy": "extended hours to accommodate increased visitors = הרחיב שעות בגלל עלייה במבקרים. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך סיבה ותוצאה", "נכון! אותה סיבה-תוצאה בדיוק", "הפוך — ''reduced'' סותר ''extended'', ו-''fewer'' סותר ''increased''", "סותר ''extended its hours''"]}', 1.31, 0.0, 0.25, 3, 'ai', NULL, true),
('e1a2da66-64b2-43ab-aa87-31b6f5050dc4', 'restatement', 'The scientist spent years developing a vaccine before it was finally approved.', NULL, '[{"id": "c", "text": "The vaccine was approved before any development took place."}, {"id": "d", "text": "The vaccine was never approved despite years of work."}, {"id": "b", "text": "It took the scientist years of development before the vaccine was approved."}, {"id": "a", "text": "The scientist developed the vaccine in a single day."}]'::jsonb, 2, '{"strategy": "spent years...before approved = בילה שנים...לפני שאושר. סדר זמן.", "correct_reason": "אותה משמעות בדיוק: שנות פיתוח קדמו לאישור.", "options_analysis": ["הופך את סדר האירועים", "סותר ''finally approved'' — הוא כן אושר בסוף", "נכון! אותה משמעות בדיוק: שנות פיתוח לפני האישור", "סותר ''spent years''"]}', 1.47, 0.0, 0.25, 3, 'ai', NULL, true),
('baba1054-c3ab-4eaf-be9e-f5a24ce75f10', 'restatement', 'The road remained closed for repairs longer than expected.', NULL, '[{"id": "c", "text": "The road repairs were completed exactly on schedule."}, {"id": "d", "text": "The road repairs finished earlier than expected."}, {"id": "a", "text": "The road was never closed for repairs."}, {"id": "b", "text": "The road stayed closed for repairs longer than people had anticipated."}]'::jsonb, 3, '{"strategy": "longer than expected = יותר זמן מהצפוי. פרט על משך הסגירה.", "correct_reason": "אותה משמעות בדיוק: הסגירה נמשכה מעבר לצפוי.", "options_analysis": ["סותר ''longer than expected''", "הפוך — ''earlier than expected'' סותר ''longer than expected''", "סותר לגמרי — הכביש כן נסגר לתיקונים", "נכון! אותה משמעות בדיוק: הסגירה נמשכה יותר מהצפוי"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('74d6e2e2-86ca-4975-a4b8-3a24df1a12fc', 'reading_comprehension', 'What is the passage mainly about?', '57017dab-bd59-405c-afbd-465513e0028c', '[{"id": "a", "text": "The destructive power and beneficial role of volcanoes"}, {"id": "c", "text": "The history of seismic sensors"}, {"id": "d", "text": "How farming communities grow crops"}, {"id": "b", "text": "Why volcanoes are impossible to study"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת גם את הסכנות וגם את התועלת של הרי געש.", "correct_reason": "כל הפסקה עוסקת בשני הצדדים של פעילות געשית: הרס ופוריות קרקע.", "options_analysis": ["נכון! הכוח ההרסני והתפקיד המועיל של הרי געש = הנושא הכולל", "פרט טכני שמוזכר, לא הנושא הכולל", "פרט משני, לא הנושא המרכזי", "הפוך — הפסקה מראה שכן ניתן לחקור, אך לא לחזות במדויק"]}', 1.2, 0.0, 0.25, 3, 'ai', NULL, true),
('212c0d95-8850-4ffa-9924-804e7d0be024', 'reading_comprehension', 'Why have farming communities historically settled near volcanoes, according to the passage?', '57017dab-bd59-405c-afbd-465513e0028c', '[{"id": "b", "text": "Because volcanoes provide free electricity"}, {"id": "c", "text": "Because volcanic ash is rich in minerals that plants need"}, {"id": "d", "text": "Because farming is illegal elsewhere"}, {"id": "a", "text": "Because volcanoes prevent all natural disasters"}]'::jsonb, 1, '{"strategy": "שאלת סיבה — חפש את ההסבר בפסקה.", "correct_reason": "הפסקה אומרת: ''volcanic ash is rich in minerals that plants need to grow''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה כלל", "לא נאמר בפסקה, וגם לא נכון עובדתית"]}', 1.05, 0.0, 0.25, 3, 'ai', NULL, true),
('c4ce1db1-bcfb-4ce0-a30c-b7fbaa67feb0', 'reading_comprehension', 'The word "fertile" in the passage most closely means:', '57017dab-bd59-405c-afbd-465513e0028c', '[{"id": "a", "text": "completely flat"}, {"id": "d", "text": "extremely dry"}, {"id": "b", "text": "good for growing plants"}, {"id": "c", "text": "poisonous and dangerous"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''the most fertile soil on Earth'' מתייחס לקרקע טובה לגידול.", "correct_reason": "fertile = פורייה, מתאימה לגידול צמחים.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "נכון! fertile = פורייה — טובה לגידול צמחים", "הפוך גמור למשמעות המילה"]}', 1.06, 0.0, 0.25, 3, 'ai', NULL, true),
('c0994daf-43ae-47b7-a555-183aa868ea48', 'reading_comprehension', 'What does modern monitoring technology allow scientists to do, according to the passage?', '57017dab-bd59-405c-afbd-465513e0028c', '[{"id": "a", "text": "Stop eruptions from happening"}, {"id": "c", "text": "Predict the exact timing of every eruption"}, {"id": "b", "text": "Control volcanic ash production"}, {"id": "d", "text": "Detect warning signs before major eruptions"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את יכולת הטכנולוגיה המודרנית בפסקה.", "correct_reason": "הפסקה אומרת: ''modern monitoring technology...now allows scientists to detect warning signs before major eruptions''.", "options_analysis": ["לא נאמר בפסקה — הטכנולוגיה מזהה סימנים, לא עוצרת התפרצויות", "סותר את הפסקה — חיזוי מדויק עדיין קשה מאוד", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.23, 0.0, 0.25, 3, 'ai', NULL, true),
