('f78a72b8-2060-479d-8430-5826ead2c683', 'reading_comprehension', 'What is the passage mainly about?', 'd809e3b1-e150-4b6f-a6c8-e7dd158e644c', '[{"id": "b", "text": "The history of clothing manufacturing"}, {"id": "d", "text": "The rise of fast fashion and its environmental and social criticisms"}, {"id": "c", "text": "Why secondhand clothing is more expensive"}, {"id": "a", "text": "How to design trendy clothing"}]'::jsonb, 1, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את תעשיית האופנה המהירה ואת הביקורת עליה.", "correct_reason": "כל הפסקה עוסקת בהתפתחות האופנה המהירה לצד הביקורת הסביבתית והחברתית עליה.", "options_analysis": ["לא מוזכר בפסקה כלל", "נכון! עליית האופנה המהירה והביקורת עליה = הנושא הכולל", "הפוך — הפסקה דווקא מעודדת אופנה איטית ויקרה יותר לאורך זמן", "לא הוראות עיצוב, אלא ניתוח תעשייתי"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('a94d4942-6b8b-4549-9d6b-569a43e14506', 'reading_comprehension', 'According to the passage, what environmental problem is linked to fast fashion materials?', 'd809e3b1-e150-4b6f-a6c8-e7dd158e644c', '[{"id": "a", "text": "They are too expensive to produce"}, {"id": "d", "text": "They require years to manufacture"}, {"id": "c", "text": "They shed microplastics and decompose slowly in landfills"}, {"id": "b", "text": "They cannot be sold at low prices"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את הבעיה הסביבתית בפסקה.", "correct_reason": "הפסקה אומרת: ''cheap synthetic materials that shed microplastics when washed and that decompose slowly in landfills''.", "options_analysis": ["סותר את הפסקה — האופנה המהירה זולה, לא יקרה", "סותר את הפסקה — הייצור מהיר, לא איטי", "נכון! נאמר במפורש בפסקה", "סותר את הפסקה — הן דווקא נמכרות בזול"]}', 1.43, 0.0, 0.25, 3, 'ai', NULL, true),
('2ad9708d-31ca-416f-8d0a-db2cf97e9198', 'reading_comprehension', 'The word "unprecedented" in the passage most closely means:', 'd809e3b1-e150-4b6f-a6c8-e7dd158e644c', '[{"id": "a", "text": "extremely expensive"}, {"id": "b", "text": "completely illegal"}, {"id": "d", "text": "very slow"}, {"id": "c", "text": "never seen before"}]'::jsonb, 3, '{"strategy": "אוצר מילים בהקשר — ''purchase trendy items at low prices with unprecedented speed''.", "correct_reason": "unprecedented = חסר תקדים, לא נראה כמותו קודם.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "הפוך — ההקשר מדבר על מהירות, לא איטיות", "נכון! unprecedented = חסר תקדים"]}', 1.06, 0.0, 0.25, 3, 'ai', NULL, true),
('1f12e1c0-7c70-433f-bfa4-fb9fb0731b2b', 'reading_comprehension', 'What labor-related criticism does the passage mention about fast fashion?', 'd809e3b1-e150-4b6f-a6c8-e7dd158e644c', '[{"id": "c", "text": "Poor working conditions and low wages in garment factories"}, {"id": "a", "text": "Workers refuse to produce clothing quickly"}, {"id": "b", "text": "There are no garment factories left"}, {"id": "d", "text": "Factory workers are paid too much"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הביקורת החברתית בפסקה.", "correct_reason": "הפסקה אומרת: ''the pressure to produce clothing quickly and cheaply has been linked to poor working conditions and low wages''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "סותר את הפסקה — יש מפעלי טקסטיל רבים", "הפוך גמור למה שנאמר בפסקה"]}', 1.09, 0.0, 0.25, 3, 'ai', NULL, true),
('e68dc031-477f-4060-a597-70bfc9bafdf1', 'reading_comprehension', 'According to the passage, what do critics say about companies'' sustainability efforts?', 'd809e3b1-e150-4b6f-a6c8-e7dd158e644c', '[{"id": "c", "text": "They are more expensive than fast fashion itself"}, {"id": "a", "text": "They remain small compared to the overall scale of production"}, {"id": "d", "text": "They have been banned by governments"}, {"id": "b", "text": "They have completely solved the environmental problems"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הביקורת על מאמצי הקיימות בפסקה.", "correct_reason": "הפסקה אומרת: ''critics argue that these efforts remain small compared to the overall scale of production''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "הפוך גמור למה שנאמר בפסקה"]}', 0.98, 0.0, 0.25, 3, 'ai', NULL, true);